# Loadable modules that have no control file -- never CREATE EXTENSION,
# only shared_preload_libraries / session_preload_libraries (or a
# replication slot's output plugin). "session": True modules work when
# loaded per session, so pgmon turns them on for the database with
# ALTER DATABASE ... SET session_preload_libraries -- no restart, and not
# blocked by a server that fixes shared_preload_libraries on its command
# line. basic_archive and basebackup_to_shell aren't offered: each does
# nothing until further server settings point at it.
MODULES = [
    {"name": "auto_explain", "description": "Logs the execution plan of every statement slower than "
     "auto_explain.log_min_duration (pgmon sets 1s) to the server log.", "preload": True, "contrib": True,
     "session": True},
    {"name": "auth_delay", "description": "Pauses before reporting a failed login, slowing down password "
     "brute-forcing.", "preload": True, "contrib": True},
    {"name": "passwordcheck", "description": "Rejects weak passwords at CREATE/ALTER ROLE.",
     "preload": True, "contrib": True},
    {"name": "pg_overexplain", "description": "Adds EXPLAIN (DEBUG, RANGE_TABLE) options showing planner "
     "internals (PostgreSQL 18+).", "preload": True, "contrib": True, "session": True},
    {"name": "test_decoding", "description": "Example logical decoding output plugin (text output).",
     "preload": False, "contrib": True},
    {"name": "wal2json", "description": "Logical decoding output plugin emitting JSON -- used by CDC tools "
     "(Debezium, AWS DMS). Create a slot with plugin 'wal2json'; needs wal_level = logical.",
     "preload": False, "deb": "postgresql-{v}-wal2json", "rpm": "wal2json_{v}"},
    {"name": "decoderbufs", "description": "Logical decoding output plugin producing Protocol Buffers, "
     "for Debezium. Used as a replication slot's plugin; needs wal_level = logical.", "preload": False,
     "deb": "postgresql-{v}-decoderbufs", "rpm": "postgres-decoderbufs_{v}"},
    {"name": "pg_failover_slots", "description": "Keeps logical replication slots in sync on physical "
     "standbys so CDC survives a failover.", "preload": True,
     "deb": "postgresql-{v}-pg-failover-slots", "rpm": "pg_failover_slots_{v}"},
    {"name": "pgextwlist", "description": "Extension whitelist: lets non-superusers create only approved "
     "extensions.", "preload": True, "deb": "postgresql-{v}-pgextwlist", "rpm": "pgextwlist_{v}"},
    {"name": "bgw_replstatus", "description": "Background worker reporting primary/standby status on a TCP "
     "port, for load balancers.", "preload": True, "deb": "postgresql-{v}-bgw-replstatus",
     "rpm": "bgw_replstatus_{v}"},
]

_CURATED_BY_NAME = {e["name"]: e for e in CURATED}
MODULES_BY_NAME = {m["name"]: m for m in MODULES}

# For index entries pgmon has no curated text for: a category from the name.
_CATEGORY_RULES = [
    (re.compile(r"_fdw$|^multicorn"), FDW),
    (re.compile(r"^pl|_pl(perl|python|tcl)"), PL),
    (re.compile(r"postgis|^h3|geo|pointcloud|routing|mobility"), GEO),
    (re.compile(r"^pg_stat|stat|monitor|_mon$"), MON),
    (re.compile(r"^pg_dbms|^ora|dbms"), ORA),
    (re.compile(r"audit|crypt|sodium|password|anon|sec"), SEC),
    (re.compile(r"vector|embed|ai$"), AI),
    (re.compile(r"repl|logical|pgq|pgpool|failover"), REPL),
]


@lru_cache(maxsize=1)
def index() -> dict:
    try:
        return json.loads(_INDEX_PATH.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return {}


def guess_category(name: str) -> str:
    for rx, cat in _CATEGORY_RULES:
        if rx.search(name):
            return cat
    return "Other"


def describe(name: str, server_comment: str | None = None) -> dict:
    """Catalog view of one extension: curated text when pgmon has it, the
    control file's own comment otherwise, and the package index entry."""
    cur = _CURATED_BY_NAME.get(name)
    idx = index().get(name, {})
    if cur:
        out = dict(cur)
    else:
        out = {"name": name, "category": guess_category(name),
               "description": server_comment or idx.get("comment") or "",
               "preload": None, "library": None, "note": None}
    out["contrib"] = bool(idx.get("contrib"))
    out["known_requires"] = idx.get("requires", [])
    out["packaged"] = bool(idx.get("deb") or idx.get("rpm"))
    return out


def all_names() -> list[str]:
    return sorted(set(index()) | set(_CURATED_BY_NAME))


def get(name: str) -> dict | None:
    """Kept for callers that only need curated metadata."""
    return _CURATED_BY_NAME.get(name)


CATALOG = CURATED  # backwards-compatible alias


# ----------------------------------------------------------- install help
def detect_platform(version_string: str) -> dict:
    """Best guess at the target's packaging from SELECT version().

    PGDG builds say so: Debian's "(Debian 17.11-1.pgdg13+2)" / older
    "pgdg120+1", Ubuntu's "(Ubuntu 16.4-1.pgdg22.04+1)", and RHEL builds
    name the compiler "(Red Hat 11.4.1-3)" -- whose GCC major tells EL8
    (8.x), EL9 (11.x) and EL10 (14.x) apart.
    """
    v = version_string or ""
    m = re.search(r"\(Debian [^)]*?pgdg(\d+)", v)
    if m:
        n = int(m.group(1))
        release = n // 10 if n >= 100 else n
        return {"family": "debian", "distro": f"Debian {release}", "label": f"Debian {release} (apt.postgresql.org)"}
    m = re.search(r"\(Ubuntu [^)]*?pgdg([\d.]+)", v)
    if m:
        return {"family": "debian", "distro": f"Ubuntu {m.group(1).rstrip('+')}",
                "label": f"Ubuntu {m.group(1).rstrip('+')} (apt.postgresql.org)"}
    if re.search(r"\((Debian|Ubuntu)", v):
        return {"family": "debian", "distro": "Debian/Ubuntu", "label": "Debian/Ubuntu (distribution packages)"}
    m = re.search(r"Red Hat (\d+)\.", v)
    if m:
        gcc = int(m.group(1))
        el = 8 if gcc <= 8 else 9 if gcc <= 12 else 10
        return {"family": "rhel", "el": el, "distro": f"EL{el}", "label": f"RHEL-family {el} (PGDG yum)"}
    if "Alpine" in v:
        return {"family": "alpine", "distro": "Alpine", "label": "Alpine (no PGDG packages)"}
    return {"family": "unknown", "distro": "unknown", "label": "unknown platform"}


def _pkg_for(entry: dict | None, major: int) -> str | None:
    if not entry or major not in entry.get("majors", []):
        return None
    if "package" in entry:
        return entry["package"].replace("{v}", str(major))
    return entry.get("by_major", {}).get(str(major))


def packages_for(name: str, major: int) -> dict:
    """{"deb": "postgresql-17-cron", "el8": "pg_cron_17", "el9": "pg_cron_17"} -- any may be None."""
    if name in MODULES_BY_NAME:
        mod = MODULES_BY_NAME[name]
        if mod.get("contrib"):
            return {"deb": f"postgresql-{major}", "el8": f"postgresql{major}-contrib",
                    "el9": f"postgresql{major}-contrib", "el10": f"postgresql{major}-contrib"}
        return {"deb": mod["deb"].replace("{v}", str(major)),
                "el8": mod["rpm"].replace("{v}", str(major)),
                "el9": mod["rpm"].replace("{v}", str(major)),
                "el10": mod["rpm"].replace("{v}", str(major))}
    idx = index().get(name, {})
    rpm = idx.get("rpm", {})
    out = {"deb": _pkg_for(idx.get("deb"), major),
           "el8": _pkg_for(rpm.get("el8"), major),
           "el9": _pkg_for(rpm.get("el9"), major)}
    # EL10 PGDG uses the same package names as EL9.
    out["el10"] = out["el9"]
    return out


def install_instructions(name: str, major: int, platform: dict) -> dict:
    """The commands to put an extension's files onto a target, for the
    target's own platform first and the other family as an alternative."""
    pk = packages_for(name, major)
    options = []
    if pk["deb"]:
        options.append({"platform": "debian", "label": "Debian / Ubuntu (apt.postgresql.org)",
                        "commands": [f"apt-get update && apt-get install -y {pk['deb']}"]})
    el = platform.get("el") or 9
    rpm = pk.get(f"el{el}") or pk.get("el9") or pk.get("el8")
    if rpm:
        cmds = [f"dnf install -y {rpm}"]
        if name.startswith(("postgis", "address_standardizer", "pgrouting", "h3", "pointcloud", "mobilitydb",
                            "ogr_fdw")):
            cmds.insert(0, f"dnf install -y epel-release && dnf config-manager --set-enabled "
                           f"{'powertools' if el == 8 else 'crb'}")
        options.append({"platform": "rhel", "label": f"RHEL / Rocky / Alma / Oracle Linux {el} (PGDG yum)",
                        "commands": cmds})
    fam = platform.get("family")
    options.sort(key=lambda o: o["platform"] != fam)
    return {"packages": pk, "options": options, "packaged": bool(options)}
